import React, { useState, useRef } from 'react';
import './UploadFile.css';
import UploadFolder from '../assets/Uploadfolder.svg';

const UploadFile = ({ onClose }) => {
  const [dragActive, setDragActive] = useState(false);
  const [files, setFiles] = useState([]);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [uploadStatus, setUploadStatus] = useState('');
  const [uploadError, setUploadError] = useState('');
  const inputRef = useRef(null);

  // Handle drag events
  const handleDrag = (e) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === "dragenter" || e.type === "dragover") {
      setDragActive(true);
    } else if (e.type === "dragleave") {
      setDragActive(false);
    }
  };

  // Handle drop event
  const handleDrop = (e) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);

    const droppedFiles = [...e.dataTransfer.files];
    if (droppedFiles?.length > 0) {
      handleFileValidation(droppedFiles);
    }
  };

  // Handle file input selection
  const handleFileInput = (e) => {
    const selectedFiles = [...e.target.files];
    if (selectedFiles?.length > 0) {
      handleFileValidation(selectedFiles);
    }
  };

  // Validate files
  const handleFileValidation = (fileList) => {
    const validFiles = fileList.filter(file => {
      const validTypes = ['text/plain', 'application/zip'];
      const maxSize = 100 * 1024 * 1024 * 1024; // 100GB
      return validTypes.includes(file.type) && file.size <= maxSize;
    });

    setFiles(validFiles);
  };

  // Format file size
  const formatFileSize = (bytes) => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  // Handle file upload
  const handleUpload = async () => {
    if (files.length === 0) return;

    try {
      setUploadStatus('uploading');
      setUploadError('');

      const formData = new FormData();
      files.forEach(file => {
        formData.append('files', file);
      });

      // Replace this with your actual upload API endpoint
      const response = await fetch('/api/upload', {
        method: 'POST',
        body: formData,
        onUploadProgress: (progressEvent) => {
          const progress = Math.round((progressEvent.loaded * 100) / progressEvent.total);
          setUploadProgress(progress);
        },
      });

      if (!response.ok) {
        throw new Error('Upload failed');
      }

      setUploadStatus('completed');
      setTimeout(() => {
        onClose();
      }, 1000);
    } catch (error) {
      console.error('Upload failed:', error);
      setUploadError('Failed to upload files. Please try again.');
      setUploadStatus('error');
    }
  };

  return (
    <div className="file-upload-modal">
      <div className="modal-content">
        <div className="modal-header">
          <h2>Please Upload your Model</h2>
        </div>

        <div className="upload-section">
          <p className="upload-instruction">Select model files for upload</p>

          <div
            className={`drop-zone ${dragActive ? 'active' : ''}`}
            onDragEnter={handleDrag}
            onDragLeave={handleDrag}
            onDragOver={handleDrag}
            onDrop={handleDrop}
          >
            <div className="upload-icon">
              <img src={UploadFolder} alt="Upload folder" />
            </div>
            <p className="drop-text">Select a file or drag and drop here</p>
            <p className="file-types">supported: txt, zip, file (no more than 100GB)</p>
            <button
              className="select-button"
              onClick={() => inputRef.current?.click()}
            >
              SELECT FILE
            </button>
            <input
              ref={inputRef}
              type="file"
              className="hidden-input"
              onChange={handleFileInput}
              multiple
              accept=".txt,.zip,.json"
            />
          </div>
        </div>

        {files.length > 0 && (
          <>
            <div className="file-list">
              <p className="file-list-header">File added</p>
              {files.map((file, index) => (
                <div key={index} className="file-item">
                  <div className="file-info">
                    <svg className="file-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor">
                      <path
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        strokeWidth="2"
                        d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"
                      />
                    </svg>
                    <span className="file-name">{file.name}</span>
                  </div>
                  <span className="file-size">{formatFileSize(file.size)}</span>
                </div>
              ))}
            </div>

            {uploadStatus === 'uploading' && (
              <div className="upload-progress">
                <div className="progress-bar">
                  <div 
                    className="progress-fill" 
                    style={{ width: `${uploadProgress}%` }} 
                  />
                </div>
                <div className="progress-status">
                  <span>Uploading...</span>
                  <span>{uploadProgress}%</span>
                </div>
              </div>
            )}

            {uploadError && (
              <div className="upload-error">
                {uploadError}
              </div>
            )}
          </>
        )}

        <div className="modal-actions">
          <button className="cancel-button" onClick={onClose}>
            Cancel
          </button>
          <button 
            className="upload-button"
            onClick={handleUpload}
            disabled={files.length === 0}
          >
            Upload
          </button>
        </div>
      </div>
    </div>
  );
};

export default UploadFile;
